from modele import *

chapitre(4,'calcul-litteral','Développer, factoriser et prouver','1 · Nombres et calculs',
'Expressions · Distributivité · Identités · Programmes de calcul',
['Transformer une expression sans changer sa valeur.','Choisir entre développement et factorisation.','Démontrer avec une lettre.'],['Produits, sommes et calculs avec les relatifs.'],[
r'''\essSection{1}{Lire et développer}
\begin{definition}Une expression littérale décrit un calcul avec des lettres. Réduire consiste à regrouper des termes semblables. Développer transforme un produit en somme.\end{definition}
\begin{propriete}La distributivité donne $k(a+b)=ka+kb$. En particulier, $-(a-b)=-a+b$. Pour deux parenthèses :
\[(a+b)(c+d)=ac+ad+bc+bd.\]\end{propriete}
\begin{exemple}$(2x-3)(x+4)=2x^2+8x-3x-12=2x^2+5x-12$. Le terme $2x^2$ est un carré multiplié par 2, pas un terme en $x$.\end{exemple}
\begin{savoirfaire}[Remplacer une lettre]Pour $x=-2$, écrire les parenthèses : $3x^2-5x=3(-2)^2-5(-2)=22$. Calculer les puissances avant les produits.\end{savoirfaire}
\begin{attention}$3x+2x=5x$, mais $3x+2$ ne se réduit pas à $5x$. Un test numérique peut détecter une erreur ; il ne démontre pas une identité pour tous les nombres.\end{attention}''',
r'''\essSection{2}{Factoriser et choisir la forme utile}
\begin{definition}Factoriser transforme une somme en produit. On cherche un facteur commun : $6x^2-9x=3x(2x-3)$.\end{definition}
\begin{propriete}La différence de deux carrés se factorise :
\[a^2-b^2=(a-b)(a+b).\]
La double distributivité permet aussi d’établir
$(a+b)^2=a^2+2ab+b^2$ et $(a-b)^2=a^2-2ab+b^2$.\end{propriete}
\begin{exemple}$4x^2-25=(2x-5)(2x+5)$. Pour calculer $99^2$, écrire $(100-1)^2=10000-200+1=9801$.\end{exemple}
\begin{savoirfaire}[Prouver avec un programme de calcul]Nommer le nombre choisi $x$, traduire chaque étape, puis transformer l’expression. Pour « ajouter 4, multiplier par 3, retirer le triple du nombre initial », on obtient $3(x+4)-3x=12$ : le résultat est indépendant de $x$.\end{savoirfaire}
\begin{attention}$(a+b)^2$ n’est généralement pas $a^2+b^2$. Il faut les deux produits croisés, dont la somme vaut $2ab$.\end{attention}'''],[
E('Remplacer une lettre',r"Calculer $A=2x^2-3x+1$ pour $x=-2$ et pour $x=3$.",r"Pour $x=-2$, $A=2\times4+6+1=\res{15}$. Pour $x=3$, $A=18-9+1=\res{10}$. Les parenthèses autour de $-2$ évitent de calculer un carré avec le mauvais signe.","Écrire la substitution avant de simplifier.","assert (2*x*x-3*x+1).subs(x,-2)==15 and (2*x*x-3*x+1).subs(x,3)==10"),
E('Réduire une expression',r"Réduire $7x-4+3x+9-2x$.",r"Les termes en $x$ donnent $(7+3-2)x=8x$. Les constantes donnent $-4+9=5$. On obtient $\res{8x+5}$. Les deux sortes de termes restent distinctes.","Regrouper seulement les termes de même nature.","assert expand(7*x-4+3*x+9-2*x)==8*x+5"),
E('Prendre l’opposé',r"Supprimer les parenthèses et réduire $-(4x-7)+2(3-x)$.",r"Le signe moins change les deux signes : $-4x+7+6-2x=\res{-6x+13}$. Le produit par 2 porte sur les deux termes de la deuxième parenthèse.","Distribuer chaque facteur à toute sa parenthèse.","assert expand(-(4*x-7)+2*(3-x))==-6*x+13"),
E('Double distributivité',r"Développer et réduire $(3x+2)(x-5)$.",r"On écrit les quatre produits : $3x^2-15x+2x-10$. Les deux termes en $x$ se regroupent, d’où $\res{3x^2-13x-10}$.","Écrire les quatre produits avant la réduction.","assert expand((3*x+2)*(x-5))==3*x*x-13*x-10"),
E('Un facteur commun',r"Factoriser $14x+21$ et $12x^2-8x$.",r"Le premier facteur commun est 7 : $\res{7(2x+3)}$. Pour le second, 4 et $x$ sont communs : $\res{4x(3x-2)}$. Redévelopper retrouve les expressions initiales.","Rechercher un facteur numérique et éventuellement littéral.","assert expand(7*(2*x+3))==14*x+21 and expand(4*x*(3*x-2))==12*x*x-8*x"),
E('Différences de carrés',r"Factoriser $x^2-81$ et $25x^2-4$.",r"On reconnaît $81=9^2$ et $25x^2=(5x)^2$. Les résultats sont $\res{(x-9)(x+9)}$ et $\res{(5x-2)(5x+2)}$.","Identifier les deux carrés avant d’appliquer l’identité.","assert expand((x-9)*(x+9))==x*x-81 and expand((5*x-2)*(5*x+2))==25*x*x-4"),
E('Deux carrés de sommes',r"Développer $(x+6)^2$ et $(2x-3)^2$.",r"Le premier développement est $\res{x^2+12x+36}$. Le second est $4x^2-12x+9$. Dans chaque cas, le terme du milieu est le double produit des deux termes de la parenthèse, avec son signe.","Conserver le double produit.","assert expand((x+6)**2)==x*x+12*x+36 and expand((2*x-3)**2)==4*x*x-12*x+9"),
E('Calculer astucieusement',r"Calculer $103\times97$ et $49^2$ en utilisant des identités.",r"$103\times97=(100+3)(100-3)=10000-9=\res{9991}$. Ensuite $(50-1)^2=2500-100+1=\res{2401}$.","Choisir un nombre rond comme point d’appui.","assert 103*97==9991 and 49**2==2401"),
E('Factoriser en deux temps',r"Factoriser $3x(x-2)+5(x-2)$, puis $9x^2-36$.",r"Dans la première expression, la parenthèse entière est commune : $\res{(x-2)(3x+5)}$. Dans la seconde, sortir 9 puis utiliser une différence de carrés : $\res{9(x-2)(x+2)}$.","Repérer un facteur commun avant une identité éventuelle.","assert expand((x-2)*(3*x+5))==expand(3*x*(x-2)+5*(x-2)) and expand(9*(x-2)*(x+2))==9*x*x-36"),
E('Tester une conjecture',r"Une élève affirme que $(x+2)^2-x^2=4$ pour tout $x$. Tester $x=1$, puis donner l’expression exacte.",r"Pour $x=1$, $9-1=8$ : l’affirmation est fausse. Le développement donne $(x^2+4x+4)-x^2=\res{4x+4}$. Le résultat vaut 4 uniquement pour $x=0$.","Utiliser un contre-exemple puis expliquer l’erreur algébrique.","assert (1+2)**2-1**2!=4 and expand((x+2)**2-x*x)==4*x+4"),
E('Deux programmes équivalents',r"Programme A : ajouter 5 au nombre choisi, multiplier par 4, retirer 8. Programme B : multiplier le nombre choisi par 4, ajouter 12. Montrer qu’ils sont équivalents.",r"Pour un nombre $x$, A donne $4(x+5)-8=4x+20-8=4x+12$. B donne directement $4x+12$. Les deux expressions sont identiques pour tout $x$. Tester seulement quelques nombres n’aurait pas suffi.","Traduire les étapes avec un nombre quelconque.","assert expand(4*(x+5)-8)==4*x+12"),
E('Une bordure',r"Un carré de côté $x$ cm est entouré d’une bordure de largeur 2 cm à l’extérieur. Exprimer l’aire de la bordure. Calculer pour $x=7$.",r"Le grand carré a pour côté $x+4$, puisque la bordure est des deux côtés. L’aire cherchée vaut $(x+4)^2-x^2=\res{8x+16}$ cm$^2$. Pour $x=7$, elle vaut $\res{72\text{ cm}^2}$. On contrôle $11^2-7^2=72$.","Soustraire les aires en calculant d’abord le bon côté extérieur.","assert expand((x+4)**2-x*x)==8*x+16 and 11**2-7**2==72",figure='bordure'),
E('Des entiers consécutifs',r"Montrer que le carré d’un entier impair est impair. Le carré d’un entier pair est-il toujours multiple de 4 ?",r"Un impair s’écrit $2n+1$ avec $n$ entier. Son carré est $4n^2+4n+1=2(2n^2+2n)+1$, donc impair. Un pair s’écrit $2n$ ; son carré vaut $4n^2$, donc est bien multiple de 4. Les preuves portent sur un entier quelconque.","Écrire la forme générale de chaque parité.","assert expand((2*n+1)**2)==2*(2*n*n+2*n)+1 and expand((2*n)**2)==4*n*n"),
E('Une égalité impossible ?',r"Deux carrés ont pour côtés positifs $x+3$ et $x$. Leur différence d’aires peut-elle valoir 9 cm$^2$ ? Peut-elle valoir 39 cm$^2$ ?",r"La différence vaut $(x+3)^2-x^2=6x+9$. Pour obtenir 9, il faudrait $x=0$, exclu par la positivité du côté. Pour 39, $6x+9=39$ donne $x=5$, qui convient. Les côtés sont alors 8 et 5 ; $64-25=39$.","Confronter la solution algébrique au domaine géométrique.","assert expand((x+3)**2-x*x)==6*x+9 and solve(6*x+9-39,x)==[5]"),
E('Une différence toujours positive',r"Comparer, pour tout réel $x$, $A=(x+1)^2$ et $B=x(x+2)$. Démontrer la réponse.",r"On calcule la différence : $A-B=x^2+2x+1-(x^2+2x)=1$. Donc $\res{A=B+1}$ pour tout $x$ ; A est toujours strictement supérieur à B. Cette méthode évite de distinguer les signes des facteurs de B.","Comparer les deux quantités par leur différence.","assert expand((x+1)**2-x*(x+2))==1")
],reperes=['Substitution, opposé et réduction','Simple et double distributivité','Factorisation et différences de carrés','Identités et preuves par le calcul'])

chapitre(5,'equations','Équations et mise en équation','1 · Nombres et calculs',
'Inconnue · Équations linéaires · Produits nuls · Validation',
['Résoudre une équation du premier degré.','Utiliser un produit nul ou un carré.','Mettre un problème en équation et valider sa solution.'],['Calcul littéral et opérations inverses.'],[
r'''\essSection{1}{Transformer une équation}
\begin{definition}Résoudre une équation, c’est trouver toutes les valeurs de l’inconnue qui rendent l’égalité vraie. Une solution se vérifie dans l’égalité initiale.\end{definition}
\begin{propriete}Ajouter ou soustraire une même quantité aux deux membres conserve les solutions. Multiplier ou diviser les deux membres par un même nombre non nul les conserve aussi.\end{propriete}
\begin{exemple}$5x-7=2x+8$ donne $3x-7=8$, puis $3x=15$, donc $x=5$. Contrôle : les deux membres initiaux valent 18.\end{exemple}
\begin{savoirfaire}[Organiser les étapes]Développer les parenthèses si nécessaire ; regrouper les termes en $x$ d’un côté et les constantes de l’autre ; isoler $x$ ; vérifier. Pour des fractions, multiplier tous les termes par un même dénominateur non nul.\end{savoirfaire}
\begin{attention}Une équation peut avoir une seule solution, aucune solution, ou tous les nombres pour solutions. $2x+3=2x+5$ est impossible ; $2(x+3)=2x+6$ est toujours vraie.\end{attention}''',
r'''\essSection{2}{Produits, carrés et problèmes}
\begin{propriete}Un produit est nul si et seulement si au moins un de ses facteurs est nul. Ainsi $(x-4)(2x+3)=0$ donne $x=4$ ou $x=-3/2$.\end{propriete}
\begin{propriete}L’équation $x^2=a$ n’a pas de solution réelle si $a<0$. Si $a=0$, sa seule solution est 0. Si $a>0$, ses deux solutions sont $-\sqrt a$ et $\sqrt a$.\end{propriete}
\begin{savoirfaire}[Mettre en équation]Choisir une inconnue et préciser son sens et son unité. Exprimer les autres quantités en fonction de cette inconnue. Traduire l’égalité du problème. Résoudre puis revenir à la situation : un nombre d’objets est entier et une longueur est positive.\end{savoirfaire}
\begin{exemple}Pour deux tarifs $3x+12$ et $5x$, l’égalité se produit à $x=6$. Comparer ensuite des valeurs ou leur différence permet de répondre à une question de choix de tarif.\end{exemple}
\begin{attention}Diviser par $x$ peut perdre la solution $x=0$. Pour $x^2=5x$, écrire $x(x-5)=0$ et conserver les deux possibilités.\end{attention}'''],[
E('Une opération inverse',r"Résoudre $x+13=4$ et $-4x=18$.",r"On soustrait 13 à la première égalité : $\res{x=-9}$. On divise la seconde par $-4$ : $\res{x=-9/2}$. Les deux équations sont indépendantes.","Appliquer l’opération inverse aux deux membres.","assert solve(x+13-4,x)==[-9] and solve(-4*x-18,x)==[Rational(-9,2)]"),
E('Deux étapes',r"Résoudre $7x-5=30$.",r"On ajoute 5 : $7x=35$. Puis on divise par 7 : $\res{x=5}$. Contrôle : $7\times5-5=30$.","Isoler le produit avant l’inconnue.","assert solve(7*x-5-30,x)==[5]"),
E('L’inconnue des deux côtés',r"Résoudre $8x+3=5x-12$.",r"On soustrait $5x$ : $3x+3=-12$. On retire 3 : $3x=-15$. Ainsi $\res{x=-5}$. Les deux membres initiaux valent $-37$.","Rassembler les termes inconnus avant les constantes.","assert solve(8*x+3-(5*x-12),x)==[-5]"),
E('Avec une parenthèse',r"Résoudre $3(2x-5)=4x+9$.",r"On développe : $6x-15=4x+9$, donc $2x=24$ et $\res{x=12}$. Vérification : $3(24-5)=57=48+9$.","Développer avant de regrouper.","assert solve(3*(2*x-5)-(4*x+9),x)==[12]"),
E('Une solution fractionnaire',r"Résoudre $5x+2=9$ et donner la solution exacte.",r"L’égalité donne $5x=7$, puis $\res{x=7/5}$. On peut écrire 1,4 ici car le décimal est exact. Une fraction n’est pas une erreur de résolution.","Conserver une valeur exacte lors de la division.","assert solve(5*x+2-9,x)==[Rational(7,5)]"),
E('Une équation fractionnaire',r"Résoudre $\dfrac{x}{3}+\dfrac{x}{4}=14$.",r"On multiplie toute l’égalité par 12 : $4x+3x=168$. Donc $7x=168$ et $\res{x=24}$. Contrôle : $24/3+24/4=8+6=14$.","Multiplier chaque terme par le même dénominateur commun.","assert solve(x/3+x/4-14,x)==[24]"),
E('Tout ou rien',r"Résoudre $4(x-2)=4x-8$, puis $4(x-2)=4x+1$.",r"La première égalité se réduit à $4x-8=4x-8$ : tous les réels sont solutions. La seconde imposerait $-8=1$ après soustraction de $4x$ : elle n’a aucune solution.","Interpréter l’égalité restante lorsque l’inconnue disparaît.","assert expand(4*(x-2)-(4*x-8))==0 and expand(4*(x-2)-(4*x+1))==-9"),
E('Un produit nul',r"Résoudre $(2x-7)(x+4)=0$.",r"Au moins un facteur est nul : $2x-7=0$ ou $x+4=0$. On obtient $\res{x=7/2\text{ ou }x=-4}$. Les deux valeurs annulent bien le produit.","Séparer les deux facteurs, pas les multiplier inutilement.","assert set(solve((2*x-7)*(x+4),x))=={Rational(7,2),-4}"),
E('Une équation de carré',r"Résoudre $x^2=49$, puis $x^2=12$, puis $x^2=-2$.",r"Les solutions sont respectivement $\res{-7\text{ et }7}$, $\res{-2\sqrt3\text{ et }2\sqrt3}$, puis aucune solution réelle. Un carré réel n’est jamais négatif.","Examiner le signe du second membre et conserver les deux racines éventuelles.","assert set(solve(x*x-49,x))=={-7,7} and set(solve(x*x-12,x))=={-2*sqrt(3),2*sqrt(3)} and solveset(x*x+2,x,domain=S.Reals)==S.EmptySet"),
E('Ne pas perdre zéro',r"Résoudre $x^2-6x=0$. Expliquer pourquoi diviser directement par $x$ est risqué.",r"On factorise $x(x-6)=0$, donc $\res{x=0\text{ ou }x=6}$. Diviser par $x$ exigerait $x\ne0$ et supprimerait la première solution. Le produit nul conserve toutes les possibilités.","Factoriser avant une division par une inconnue.","assert set(solve(x*x-6*x,x))=={0,6}"),
E('Des billets de spectacle',r"Un groupe achète 28 billets : les billets jeunes coûtent 6 €, les autres 10 €. La dépense totale est 232 €. Combien de billets jeunes ?",r"Notons $x$ le nombre de jeunes ; il y a $28-x$ autres billets. L’équation est $6x+10(28-x)=232$, soit $280-4x=232$. Ainsi $\res{x=12}$. Il reste 16 autres billets ; $72+160=232$. La solution est entière et comprise entre 0 et 28.","Exprimer les deux effectifs avec une seule inconnue.","assert solve(6*x+10*(28-x)-232,x)==[12]"),
E('Un rectangle à retrouver',r"Un rectangle a un périmètre de 58 cm. Sa longueur dépasse sa largeur de 7 cm. Déterminer ses dimensions et son aire.",r"Notons $x$ sa largeur, sa longueur vaut $x+7$. Alors $2x+2(x+7)=58$, donc $4x=44$ et $x=11$. Les dimensions sont $\res{11\text{ cm et }18\text{ cm}}$, l’aire $\res{198\text{ cm}^2}$.","Traduire le périmètre avec les deux côtés.","assert solve(2*x+2*(x+7)-58,x)==[11] and 11*18==198",figure='rectangle-equation'),
E('Retrouver le nombre initial',r"On ajoute 4 à un nombre, on multiplie le résultat par 3, puis on soustrait le double du nombre de départ. Le résultat est 25. Retrouver le nombre.",r"Pour un départ $x$, le résultat vaut $3(x+4)-2x=x+12$. L’équation $x+12=25$ donne $\res{x=13}$. Vérification : $17\times3-26=25$. La traduction distingue le résultat courant et le nombre initial.","Nommer le nombre initial tout au long du programme.","assert solve(3*(x+4)-2*x-25,x)==[13]"),
E('Un achat rentable',r"Une bouteille filtrante coûte 38 €. Ses recharges coûtent 12 € par an. Elle évite un achat estimé à 30 € de bouteilles chaque année. À partir de quelle année entière la dépense cumulée devient-elle inférieure ou égale à l’ancien achat ?",r"Après $n$ années, les dépenses sont $38+12n$ et $30n$. Il faut économiser au moins les 38 € initiaux ; le gain annuel est $30-12=18$ €. Or $2\times18=36<38$ et $3\times18=54\ge38$. La première année entière est $\res3$. Contrôle : 74 € contre 90 € à trois ans.","Calculer le gain annuel puis tester les entiers autour du seuil.","assert 38+12*2>30*2 and 38+12*3<=30*3"),
E('Deux aires égales',r"Un carré de côté $x+2$ cm et un rectangle de côtés $x$ cm et $x+5$ cm ont la même aire. Les dimensions sont positives. Déterminer $x$ et l’aire commune.",r"On pose $(x+2)^2=x(x+5)$. Après développement : $x^2+4x+4=x^2+5x$, donc $\res{x=4}$. Le carré a pour côté 6 et le rectangle pour côtés 4 et 9. L’aire commune est $\res{36\text{ cm}^2}$. Toutes les dimensions sont positives.","Développer pour faire disparaître les termes carrés communs.","assert solve((x+2)**2-x*(x+5),x)==[4] and (4+2)**2==4*(4+5)==36",figure='aires-egales')
],reperes=['Équations du premier degré','Équations produits et carrés','Cas particuliers et validation','Modélisation de situations'])

chapitre(6,'proportionnalite','Proportionnalité, ratios et pourcentages','2 · Grandeurs et fonctions',
'Coefficients · Échelles · Évolutions · Comparaisons',
['Reconnaître une proportionnalité.','Utiliser un ratio ou une échelle.','Appliquer et interpréter des pourcentages.'],['Fractions et produits.'],[
r'''\essSection{1}{Reconnaître une proportionnalité}
\begin{definition}Deux grandeurs sont proportionnelles si l’on obtient les valeurs de l’une en multipliant celles de l’autre par un même coefficient. Le graphique est alors une droite passant par l’origine.\end{definition}
\begin{savoirfaire}[Choisir une méthode]Utiliser le passage à l’unité, un coefficient, la linéarité ou un produit en croix. Si 3 kg coûtent 7,20 €, 1 kg coûte 2,40 €, et 5 kg coûtent 12 €.\end{savoirfaire}
\begin{definition}Un ratio $a:b$ partage une quantité en $a+b$ parts égales, avec $a$ parts pour le premier terme. Pour un ratio $2:3$ sur 35 L, les volumes sont $14$ L et $21$ L.\end{definition}
\begin{definition}Une échelle est le rapport longueur sur le plan sur longueur réelle, dans la même unité. À l’échelle $1/500$, 1 cm sur le plan représente 500 cm, soit 5 m.\end{definition}
\begin{attention}Un tarif avec un forfait fixe n’est pas proportionnel au nombre d’unités. Deux valeurs qui augmentent ensemble ne sont pas forcément proportionnelles.\end{attention}''',
r'''\essSection{2}{Appliquer et comprendre un pourcentage}
\begin{propriete}Calculer $t\,\%$ d’une quantité revient à la multiplier par $t/100$. Une hausse de $t\,\%$ multiplie par $1+t/100$ ; une baisse par $1-t/100$.\end{propriete}
\begin{exemple}Après une baisse de 15\,\%, un prix de 80 € devient $80\times0{,}85=68$ €. Retrouver le prix initial exige de diviser par 0,85.\end{exemple}
\begin{savoirfaire}[Évolutions successives]Multiplier les coefficients, sans additionner les taux. Une hausse de 20\,\% suivie d’une baisse de 20\,\% donne $1{,}2\times0{,}8=0{,}96$ : la baisse totale est de 4\,\%.\end{savoirfaire}
\begin{propriete}Le taux d’évolution de $V_i>0$ à $V_f$ vaut $(V_f-V_i)/V_i$. Préciser la valeur initiale choisie comme référence.\end{propriete}
\begin{attention}Passer de 30\,\% à 36\,\% représente 6 points de pourcentage, mais une augmentation relative de $6/30=20\,\%$. Ces deux informations ne répondent pas à la même question.\end{attention}'''],[
E('Passer par l’unité',r"Quatre cahiers coûtent 10,80 €. Le prix est proportionnel au nombre de cahiers. Quel prix pour sept cahiers ?",r"Un cahier coûte $10{,}80/4=2{,}70$ €. Sept coûtent $7\times2{,}70=\res{18{,}90\text{ €}}$.","Calculer le prix d’une unité avant celui du lot.","assert Rational('10.80')/4*7==Rational('18.90')"),
E('Un tableau proportionnel ?',r"Les couples quantité-prix sont $(2;7)$, $(5;17{,}5)$ et $(8;28)$. Le tableau est-il proportionnel ?",r"Les trois rapports prix sur quantité valent $7/2=17{,}5/5=28/8=3{,}5$. Le coefficient est donc $\res{3{,}5}$ ; le tableau est proportionnel.","Comparer tous les rapports correspondant à la même direction.","assert Rational(7,2)==Rational('17.5')/5==Rational(28,8)"),
E('Appliquer une réduction',r"Un sac coûte 64 €. Son prix baisse de 25 \%. Calculer le nouveau prix.",r"Le coefficient est $1-25/100=0{,}75$. Le nouveau prix vaut $64\times0{,}75=\res{48\text{ €}}$. La réduction est de 16 €.","Multiplier par le coefficient de baisse.","assert 64*Rational(75,100)==48"),
E('Calculer un taux',r"Un effectif passe de 160 à 184. Quel est son taux d’augmentation ?",r"La hausse vaut $184-160=24$. Rapportée à l’effectif initial, elle représente $24/160=0{,}15$, soit $\res{15\,\%}$.","Diviser la variation par la valeur de départ.","assert Rational(184-160,160)==Rational(15,100)"),
E('Partager selon un ratio',r"Partager 56 billes selon le ratio $3:5$.",r"Il y a $3+5=8$ parts, chacune de $56/8=7$ billes. Les deux groupes reçoivent $\res{21\text{ et }35\text{ billes}}$. Le total et le ratio sont vérifiés.","Compter toutes les parts du ratio.","assert 56//8*3==21 and 56//8*5==35"),
E('Retrouver un prix initial',r"Après une hausse de 8 \%, un abonnement coûte 81 €. Quel était son prix ?",r"Si le prix initial est $P$, $1{,}08P=81$. Ainsi $P=81/1{,}08=\res{75\text{ €}}$. Soustraire 8 \% de 81 utiliserait une autre référence.","Diviser par le coefficient d’évolution.","assert Rational(81)/Rational('1.08')==75"),
E('Deux baisses',r"Un prix de 250 € baisse de 10 \%, puis de 20 \%. Calculer le prix final et la réduction globale.",r"Les coefficients se multiplient : $250\times0{,}9\times0{,}8=\res{180\text{ €}}$. Le coefficient global est 0,72, donc la baisse totale est $\res{28\,\%}$, et non 30 \%.","Appliquer chaque taux à la valeur actualisée.","assert 250*Rational(9,10)*Rational(8,10)==180 and 1-Rational(9,10)*Rational(8,10)==Rational(28,100)"),
E('Une échelle',r"Deux lieux distants de 7,2 km sont séparés de 9 cm sur une carte. Déterminer l’échelle.",r"On convertit 7,2 km en 720000 cm. Le rapport plan sur réel vaut $9/720000=1/80000$. L’échelle est $\res{1:80000}$.","Mettre les longueurs dans la même unité.","assert Rational(9,720000)==Rational(1,80000)"),
E('Une recette à trois termes',r"Une boisson est préparée selon le ratio sirop : eau : jus $=1:6:3$. Pour 4,5 L de boisson, calculer chaque volume.",r"Les dix parts totalisent 4,5 L ; une part vaut 0,45 L. Les volumes sont donc $\res{0{,}45\text{ L},\ 2{,}70\text{ L},\ 1{,}35\text{ L}}$. Leur somme vaut bien 4,5 L.","Additionner les termes du ratio avant de partager.","assert sum([Rational(45,100),Rational(270,100),Rational(135,100)])==Rational(45,10)"),
E('Un tarif avec forfait',r"Une livraison coûte 5 € de préparation, puis 2 € par colis. Le coût est-il proportionnel au nombre de colis ? Calculer pour 3 et 6 colis.",r"Les prix sont $5+2\times3=\res{11\text{ €}}$ et $5+2\times6=\res{17\text{ €}}$. Doubler le nombre de colis ne double pas le coût : le forfait fixe empêche la proportionnalité.","Tester le rôle d’une somme fixe.","assert 5+2*3==11 and 5+2*6==17 and 2*11!=17"),
E('Comparer deux promotions',r"Un article coûte 120 €. Offre A : réduction de 30 €. Offre B : réduction de 20 \%, puis bon d’achat de 10 € utilisable immédiatement sur cet achat. Comparer les paiements.",r"A conduit à $120-30=\res{90\text{ €}}$. B conduit à $120\times0{,}8-10=\res{86\text{ €}}$. Avec les conditions indiquées, B fait payer 4 € de moins. Le calcul dépend de l’utilisation immédiate du bon.","Traduire exactement l’ordre des avantages.","assert 120-30==90 and 120*Rational(8,10)-10==86"),
E('Un mélange à corriger',r"On mélange 2 L de sirop avec 8 L d’eau. On veut que le sirop représente 16 \% du mélange sans en retirer. Quel volume d’eau ajouter ?",r"Les 2 L de sirop doivent représenter 0,16 du volume final $V$ : $V=2/0{,}16=12{,}5$ L. Le mélange initial fait 10 L. Il faut ajouter $\res{2{,}5\text{ L d’eau}}$. Le numérateur reste 2, mais le total augmente.","Fixer la quantité conservée et chercher le nouveau total.","assert Rational(2)/(10+Rational(25,10))==Rational(16,100)"),
E('Deux pourcentages emboîtés',r"Dans un collège de 720 élèves, 45 \% sont inscrits à l’association sportive. Parmi les inscrits, $2/9$ pratiquent le badminton. Quel est leur effectif et leur part dans le collège ?",r"L’association compte $720\times0{,}45=324$ élèves. Le badminton en compte $324\times2/9=\res{72}$. Leur part dans le collège est $72/720=\res{10\,\%}$. On multiplie 45 \% par $2/9$, pas par 2.","Nommer le groupe de référence de chaque proportion.","assert 720*Rational(45,100)*Rational(2,9)==72 and Rational(72,720)==Rational(1,10)"),
E('Revenir après une baisse',r"Un prix baisse de 20 \%. Quelle augmentation en pourcentage permet de revenir au prix initial ?",r"Après la baisse, le coefficient est 0,8. Pour annuler son effet, il faut multiplier par $1/0{,}8=1{,}25$, soit une hausse de $\res{25\,\%}$. Exemple : 100 € devient 80 €, puis 100 €.","Chercher le coefficient multiplicateur inverse.","assert 1/Rational(8,10)-1==Rational(25,100)"),
E('Lire une annonce',r"La part des élèves venant à vélo passe de 12 \% à 15 \%. Une annonce parle de « 3 \% de hausse ». Expliquer précisément l’évolution. Sur 800 élèves à effectif constant, combien de cyclistes supplémentaires ?",r"La part augmente de $\res{3\text{ points}}$. Relativement à 12 \%, la hausse vaut $(15-12)/12=\res{25\,\%}$. Les effectifs passent de 96 à 120, soit $\res{24}$ cyclistes supplémentaires. Le maintien du total de 800 est indispensable à cette dernière comparaison.","Distinguer points de pourcentage, taux relatif et effectifs.","assert Rational(15-12,12)==Rational(1,4) and 800*Rational(3,100)==24")
],reperes=['Proportionnalité et coefficients','Ratios et échelles','Évolutions et prix initiaux','Comparaisons et pourcentages emboîtés'])
